1	import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
2	import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
3	import { z } from 'zod';
4	import { ChessApiClient, ApiError, getConnection, closeConnection, closeAllConnections } from './api-client.js';
5	import { loadCredentials, saveCredentials } from './auth-store.js';
6	
7	const serverUrl = process.env.CHESS_SERVER_URL || 'http://localhost:3001';
8	const client = new ChessApiClient(serverUrl);
9	
10	const server = new McpServer({
11	  name: 'onchainchess',
12	  version: '1.0.0',
13	});
14	
15	function requireAuth() {
16	  const creds = loadCredentials();
17	  if (!creds) {
18	    throw new Error('No account found. Use create_account first.');
19	  }
20	  return creds;
21	}
22	
23	// Wrap a tool handler to auto-refresh on token expiry and retry once
24	function withAutoRefresh(handler) {
25	  return async (args) => {
26	    try {
27	      return await handler(args);
28	    } catch (err) {
29	      if (err instanceof ApiError && err.status === 401 && err.message === 'token_expired') {
30	        // Attempt token refresh
31	        const creds = loadCredentials();
32	        if (!creds) throw err;
33	        try {
34	          const result = await client.refresh(creds.token);
35	          saveCredentials(result.username, result.token);
36	          // Retry the original handler with refreshed credentials
37	          return await handler(args);
38	        } catch (refreshErr) {
39	          throw new Error('Token expired and refresh failed. Use create_account to re-register.');
40	        }
41	      }
42	      throw err;
43	    }
44	  };
45	}
46	
47	function errorResponse(err) {
48	  const message = err instanceof ApiError
49	    ? err.message
50	    : err.message || 'Unknown error';
51	  const result = { error: message };
52	  if (err instanceof ApiError && err.body?.legalMoves) {
53	    result.legalMoves = err.body.legalMoves;
54	  }
55	  return { content: [{ type: 'text', text: JSON.stringify(result) }], isError: true };
56	}
57	
58	function ok(data) {
59	  return { content: [{ type: 'text', text: JSON.stringify(data) }] };
60	}
61	
62	// 1. create_account
63	server.tool(
64	  'create_account',
65	  'Create a bot account on onchainchess.com. Only needed once — credentials are saved to disk.',
66	  { username: z.string().min(3).max(32).describe('Username (3-32 chars, alphanumeric + hyphens)') },
67	  async ({ username }) => {
68	    try {
69	      const existing = loadCredentials();
70	      if (existing) {
71	        return errorResponse(new Error(`Account already exists: ${existing.username}. Delete ~/.onchainchess-bot to create a new one.`));
72	      }
73	      const result = await client.signup(username);
74	      saveCredentials(result.username, result.token);
75	      return ok({ username: result.username, message: 'Account created and saved.' });
76	    } catch (err) {
77	      return errorResponse(err);
78	    }
79	  }
80	);
81	
82	// 2. create_game
83	server.tool(
84	  'create_game',
85	  'Create a new chess game room. Returns an invite code to share with your opponent.',
86	  { color: z.enum(['white', 'black', 'random']).default('random').describe('Which color to play as') },
87	  async ({ color }) => {
88	    try {
89	      return await withAutoRefresh(async () => {
90	        const { token } = requireAuth();
91	        const room = await client.createRoom(token, color);
92	        const conn = getConnection(room.roomId, client.wsUrl, token);
93	        await conn.ready();
94	        return ok({ roomId: room.roomId, inviteCode: room.inviteCode, color: room.color });
95	      })();
96	    } catch (err) {
97	      return errorResponse(err);
98	    }
99	  }
100	);
101	
102	// 3. wait_for_opponent
103	server.tool(
104	  'wait_for_opponent',
105	  'Wait for an opponent to join your game room. Blocks until someone joins or timeout.',
106	  {
107	    room_id: z.number().describe('Room ID to wait in'),
108	    timeout_seconds: z.number().default(300).describe('Max seconds to wait (default 300)'),
109	  },
110	  async ({ room_id, timeout_seconds }) => {
111	    try {
112	      return await withAutoRefresh(async () => {
113	        const { token } = requireAuth();
114	        const conn = getConnection(room_id, client.wsUrl, token);
115	        await conn.ready();
116	
117	        const state = await client.getRoomState(token, room_id);
118	        if (state.status === 'playing') {
119	          return ok({
120	            status: 'playing',
121	            opponent_username: state.white?.username === state.myUsername ? state.black?.username : state.white?.username,
122	          });
123	        }
124	
125	        const msg = await conn.waitForEvent(['join'], timeout_seconds * 1000);
126	        return ok({
127	          status: 'playing',
128	          opponent_username: msg.data?.username,
129	          opponent_color: msg.data?.color,
130	        });
131	      })();
132	    } catch (err) {
133	      return errorResponse(err);
134	    }
135	  }
136	);
137	
138	// 4. join_game
139	server.tool(
140	  'join_game',
141	  'Join an existing game using an invite code.',
142	  { invite_code: z.string().describe('The invite code shared by the game creator') },
143	  async ({ invite_code }) => {
144	    try {
145	      return await withAutoRefresh(async () => {
146	        const { token } = requireAuth();
147	        const result = await client.joinRoom(token, invite_code);
148	        const conn = getConnection(result.roomId, client.wsUrl, token);
149	        await conn.ready();
150	        return ok({ roomId: result.roomId, color: result.color });
151	      })();
152	    } catch (err) {
153	      return errorResponse(err);
154	    }
155	  }
156	);
157	
158	// 5. get_board_state
159	server.tool(
160	  'get_board_state',
161	  'Get the current board state, legal moves, and game status.',
162	  { room_id: z.number().describe('Room ID') },
163	  async ({ room_id }) => {
164	    try {
165	      return await withAutoRefresh(async () => {
166	        const { token } = requireAuth();
167	        const state = await client.getRoomState(token, room_id);
168	        return ok(state);
169	      })();
170	    } catch (err) {
171	      return errorResponse(err);
172	    }
173	  }
174	);
175	
176	// 6. make_move
177	server.tool(
178	  'make_move',
179	  'Make a chess move in UCI format (e.g. "e2e4", "e7e8q" for promotion).',
180	  {
181	    room_id: z.number().describe('Room ID'),
182	    move: z.string().describe('Move in UCI format: source+target+promotion (e.g. "e2e4", "e7e8q")'),
183	  },
184	  async ({ room_id, move }) => {
185	    try {
186	      return await withAutoRefresh(async () => {
187	        const { token } = requireAuth();
188	        const result = await client.submitMove(token, room_id, move);
189	        return ok(result);
190	      })();
191	    } catch (err) {
192	      return errorResponse(err);
193	    }
194	  }
195	);
196	
197	// 7. wait_for_turn
198	server.tool(
199	  'wait_for_turn',
200	  'Wait for it to be your turn (or game over). Blocks until opponent moves or timeout.',
201	  {
202	    room_id: z.number().describe('Room ID'),
203	    timeout_seconds: z.number().default(300).describe('Max seconds to wait (default 300)'),
204	  },
205	  async ({ room_id, timeout_seconds }) => {
206	    try {
207	      return await withAutoRefresh(async () => {
208	        const { token } = requireAuth();
209	        const conn = getConnection(room_id, client.wsUrl, token);
210	        await conn.ready();
211	
212	        const state = await client.getRoomState(token, room_id);
213	        if (state.status === 'finished') {
214	          closeConnection(room_id);
215	          return ok(state);
216	        }
217	        if (state.currentTurn === state.myColor) {
218	          return ok(state);
219	        }
220	
221	        const msg = await conn.waitForEvent(['move', 'gameOver'], timeout_seconds * 1000);
222	
223	        if (msg.event === 'gameOver') {
224	          closeConnection(room_id);
225	          return ok({ gameOver: true, result: msg.data?.result, reason: msg.data?.reason });
226	        }
227	
228	        const updated = await client.getRoomState(token, room_id);
229	        return ok(updated);
230	      })();
