1	import { z } from 'zod';
2	import { config } from './config.js';
3	import { chessApi } from './chess-api.js';
4	import { getConnection, closeConnection } from './game-ws.js';
5	
6	// Chess WebSocket URL derived from chess server URL.
7	const wsUrl = config.chessServerUrl.replace(/^http/, 'ws');
8	
9	// Wrap a tool body so 401 from the chess API triggers an automatic agent-token
10	// refresh + retry once. Refreshed token is persisted to the access token's
11	// authorization row via the provided updater callback.
12	function withTokenRefresh(ctx, fn) {
13	  return async (args) => {
14	    try {
15	      return await fn(args, ctx.agent_chess_token);
16	    } catch (err) {
17	      if (err && err.status === 401) {
18	        const fresh = await chessApi.rotateAgentToken(ctx.agent_user_id);
19	        ctx.updateAgentToken(fresh.chess_token);
20	        ctx.agent_chess_token = fresh.chess_token;
21	        return await fn(args, fresh.chess_token);
22	      }
23	      throw err;
24	    }
25	  };
26	}
27	
28	function ok(data) {
29	  return { content: [{ type: 'text', text: JSON.stringify(data) }] };
30	}
31	function errorResponse(err) {
32	  const message = err?.message || 'Unknown error';
33	  const result = { error: message };
34	  if (err?.body?.legalMoves) result.legalMoves = err.body.legalMoves;
35	  return { content: [{ type: 'text', text: JSON.stringify(result) }], isError: true };
36	}
37	
38	// Trim move/state responses to only what the agent needs to pick the next move.
39	// FEN encodes side-to-move + position, so board[] / currentTurn / moveHistory
40	// are dropped. Use get_board_state for the full payload.
41	function slim(state) {
42	  const out = {
43	    fen: state.fen,
44	    legalMoves: state.legalMoves,
45	    gameOver: state.gameOver === true || state.status === 'finished',
46	  };
47	  if (state.result) out.result = state.result;
48	  if (state.reason) out.reason = state.reason;
49	  return out;
50	}
51	
52	export function registerTools(server, ctx) {
53	  // ctx = { agent_user_id, agent_chess_token, updateAgentToken(newToken) }
54	
55	  server.tool(
56	    'create_game',
57	    'Create a new chess game room. Returns an invite code to share with your opponent.',
58	    { color: z.enum(['white', 'black', 'random']).default('random').describe('Which color to play as') },
59	    async ({ color }) => {
60	      try {
61	        return await withTokenRefresh(ctx, async (_args, token) => {
62	          const room = await chessApi.chessRequest('/api/rooms', {
63	            method: 'POST', token, body: { color },
64	          });
65	          const conn = getConnection(room.roomId, wsUrl, token);
66	          await conn.ready();
67	          return ok({ roomId: room.roomId, inviteCode: room.inviteCode, color: room.color });
68	        })({ color });
69	      } catch (err) { return errorResponse(err); }
70	    }
71	  );
72	
73	  server.tool(
74	    'wait_for_opponent',
75	    'Wait for an opponent to join your game room. Blocks until someone joins or timeout.',
76	    {
77	      room_id: z.number().describe('Room ID to wait in'),
78	      timeout_seconds: z.number().default(60).describe('Max seconds to wait (default 60, max 90)'),
79	    },
80	    async ({ room_id, timeout_seconds }) => {
81	      try {
82	        return await withTokenRefresh(ctx, async (_args, token) => {
83	          const cap = Math.min(timeout_seconds, 90);
84	          const conn = getConnection(room_id, wsUrl, token);
85	          await conn.ready();
86	          const state = await chessApi.chessRequest(`/api/rooms/${room_id}`, { token });
87	          if (state.status === 'playing') {
88	            return ok({
89	              status: 'playing',
90	              opponent_username: state.white?.username === state.myUsername
91	                ? state.black?.username
92	                : state.white?.username,
93	            });
94	          }
95	          const msg = await conn.waitForEvent(['join'], cap * 1000);
96	          return ok({
97	            status: 'playing',
98	            opponent_username: msg.data?.username,
99	            opponent_color: msg.data?.color,
100	          });
101	        })({ room_id, timeout_seconds });
102	      } catch (err) { return errorResponse(err); }
103	    }
104	  );
105	
106	  server.tool(
107	    'join_game',
108	    'Join an existing game using an invite code.',
109	    { invite_code: z.string().describe('The invite code shared by the game creator') },
110	    async ({ invite_code }) => {
111	      try {
112	        return await withTokenRefresh(ctx, async (_args, token) => {
113	          const result = await chessApi.chessRequest('/api/rooms/join', {
114	            method: 'POST', token, body: { inviteCode: invite_code },
115	          });
116	          const conn = getConnection(result.roomId, wsUrl, token);
117	          await conn.ready();
118	          return ok({ roomId: result.roomId, color: result.color });
119	        })({ invite_code });
120	      } catch (err) { return errorResponse(err); }
121	    }
122	  );
123	
124	  server.tool(
125	    'get_board_state',
126	    'Get the current board state, legal moves, and game status.',
127	    { room_id: z.number().describe('Room ID') },
128	    async ({ room_id }) => {
129	      try {
130	        return await withTokenRefresh(ctx, async (_args, token) => {
131	          const state = await chessApi.chessRequest(`/api/rooms/${room_id}`, { token });
132	          return ok(state);
133	        })({ room_id });
134	      } catch (err) { return errorResponse(err); }
135	    }
136	  );
137	
138	  server.tool(
139	    'make_move',
140	    'Make a chess move in UCI format (e.g. "e2e4", "e7e8q" for promotion).',
141	    {
142	      room_id: z.number().describe('Room ID'),
143	      move: z.string().describe('Move in UCI format: source+target+promotion (e.g. "e2e4", "e7e8q")'),
144	    },
145	    async ({ room_id, move }) => {
146	      try {
147	        return await withTokenRefresh(ctx, async (_args, token) => {
148	          const result = await chessApi.chessRequest(`/api/rooms/${room_id}/move`, {
149	            method: 'POST', token, body: { move },
150	          });
151	          return ok(slim(result));
152	        })({ room_id, move });
153	      } catch (err) { return errorResponse(err); }
154	    }
155	  );
156	
157	  server.tool(
158	    'wait_for_turn',
159	    'Wait for it to be your turn (or game over). Blocks until opponent moves or timeout.',
160	    {
161	      room_id: z.number().describe('Room ID'),
162	      timeout_seconds: z.number().default(60).describe('Max seconds to wait (default 60, max 90)'),
163	    },
164	    async ({ room_id, timeout_seconds }) => {
165	      try {
166	        return await withTokenRefresh(ctx, async (_args, token) => {
167	          const cap = Math.min(timeout_seconds, 90);
168	          const conn = getConnection(room_id, wsUrl, token);
169	          await conn.ready();
170	          const state = await chessApi.chessRequest(`/api/rooms/${room_id}`, { token });
171	          if (state.status === 'finished') {
172	            closeConnection(room_id, token);
173	            return ok(slim(state));
174	          }
175	          if (state.currentTurn === state.myColor) return ok(slim(state));
176	
177	          const msg = await conn.waitForEvent(['move', 'gameOver'], cap * 1000);
178	          if (msg.event === 'gameOver') {
179	            closeConnection(room_id, token);
180	            return ok({ gameOver: true, result: msg.data?.result, reason: msg.data?.reason });
181	          }
182	          const updated = await chessApi.chessRequest(`/api/rooms/${room_id}`, { token });
183	          return ok(slim(updated));
184	        })({ room_id, timeout_seconds });
