1	import { useEffect, useRef, useState } from 'react';
2	import { useLocation, useNavigate } from 'react-router-dom';
3	import { MCP_SERVER_URL } from '../config';
4	import { usePasskeyAuth } from '../hooks/usePasskeyAuth';
5	import './AuthPages.css';
6	
7	// Phases:
8	//   loading      – fetching client info
9	//   resolving    – calling passkey-resolve / has-agent
10	//   name-agent   – first-time auth for this client; ask for agent name
11	//   submitting   – provision-agent / issue-consent / authorize/complete in flight
12	//   error        – terminal error
13	//   expired      – auth_request expired or missing
14	
15	export default function AuthPage() {
16	  const passkey = usePasskeyAuth();
17	  const navigate = useNavigate();
18	  const location = useLocation();
19	  const requestId = new URLSearchParams(location.search).get('request_id');
20	
21	  const [phase, setPhase] = useState('loading');
22	  const [client, setClient] = useState(null);
23	  const [errorMsg, setErrorMsg] = useState(null);
24	  const [humanUserId, setHumanUserId] = useState(null);
25	  const [agentUsername, setAgentUsername] = useState('');
26	
27	  const resolveStartedRef = useRef(false);
28	
29	  // 1. Load OAuth params for this request_id.
30	  useEffect(() => {
31	    if (!requestId) {
32	      setPhase('expired');
33	      setErrorMsg('Missing request_id. Start the connection from your AI client.');
34	      return;
35	    }
36	    let cancelled = false;
37	    (async () => {
38	      try {
39	        const resp = await fetch(`${MCP_SERVER_URL}/authorize/lookup?request_id=${encodeURIComponent(requestId)}`);
40	        if (cancelled) return;
41	        if (resp.status === 410 || resp.status === 404) {
42	          setPhase('expired');
43	          setErrorMsg('This authorization session has expired. Retry from your AI client.');
44	          return;
45	        }
46	        if (!resp.ok) {
47	          const data = await resp.json().catch(() => ({}));
48	          throw new Error(data.error || `Lookup failed (${resp.status})`);
49	        }
50	        const data = await resp.json();
51	        setClient(data);
52	        // If user isn't signed in, we route them off this page entirely.
53	        if (!passkey.isAuthenticated) {
54	          navigate(`/signin-required?request_id=${encodeURIComponent(requestId)}`, { replace: true });
55	        }
56	      } catch (err) {
57	        if (cancelled) return;
58	        setPhase('error');
59	        setErrorMsg(err.message || 'Network error');
60	      }
61	    })();
62	    return () => { cancelled = true; };
63	  }, [requestId, passkey.isAuthenticated, navigate]);
64	
65	  // 2. Once authenticated and client info loaded, kick off resolve → has-agent.
66	  useEffect(() => {
67	    if (!client || !passkey.isAuthenticated || resolveStartedRef.current) return;
68	    resolveStartedRef.current = true;
69	    runResolveAndHasAgent();
70	    // eslint-disable-next-line react-hooks/exhaustive-deps
71	  }, [client, passkey.isAuthenticated]);
72	
73	  async function runResolveAndHasAgent() {
74	    setPhase('resolving');
75	    try {
76	      const resolveResp = await fetch(`${MCP_SERVER_URL}/authorize/passkey-resolve`, {
77	        method: 'POST',
78	        headers: { 'Content-Type': 'application/json' },
79	        body: JSON.stringify({
80	          request_id: requestId,
81	          passkeyAddress: passkey.account,
82	          credentialId: passkey.credentialId,
83	        }),
84	      });
85	      if (resolveResp.status === 404) {
86	        // Edge case: passkey verified but no chess account row. Rare —
87	        // shouldn't happen with persistent storage. Send them through
88	        // sign-in flow to re-bridge the chess account.
89	        navigate(`/signin-required?request_id=${encodeURIComponent(requestId)}`, { replace: true });
90	        return;
91	      }
92	      if (!resolveResp.ok) {
93	        const data = await resolveResp.json().catch(() => ({}));
94	        throw new Error(data.error || `passkey-resolve failed (${resolveResp.status})`);
95	      }
96	      const { user_id } = await resolveResp.json();
97	      setHumanUserId(user_id);
98	
99	      const hasResp = await fetch(`${MCP_SERVER_URL}/authorize/has-agent`, {
100	        method: 'POST',
101	        headers: { 'Content-Type': 'application/json' },
102	        body: JSON.stringify({ request_id: requestId, human_user_id: user_id }),
103	      });
104	      if (!hasResp.ok) {
105	        const data = await hasResp.json().catch(() => ({}));
106	        throw new Error(data.error || `has-agent failed (${hasResp.status})`);
107	      }
108	      const { agent } = await hasResp.json();
109	      if (agent) {
110	        await finalize({ human_user_id: user_id, agent_user_id: agent.agent_user_id });
111	      } else {
112	        setPhase('name-agent');
113	      }
114	    } catch (err) {
115	      setPhase('error');
116	      setErrorMsg(err.message || 'Network error');
117	    }
118	  }
