124	      if (agent_user_id) provBody.agent_user_id = agent_user_id;
125	      else provBody.agent_username = agent_username;
126	      const provResp = await fetch(`${MCP_SERVER_URL}/authorize/provision-agent`, {
127	        method: 'POST',
128	        headers: { 'Content-Type': 'application/json' },
129	        body: JSON.stringify(provBody),
130	      });
131	      if (!provResp.ok) {
132	        const data = await provResp.json().catch(() => ({}));
133	        throw new Error(data.error || `Provisioning failed (${provResp.status})`);
134	      }
135	      const provision = await provResp.json();
136	
