20	// Wrap a tool body so 401 from the chess API triggers an automatic agent-token
21	// refresh + retry once. Refreshed token is persisted to the access token's
22	// authorization row via the provided updater callback.
23	function withTokenRefresh(ctx, fn) {
24	  return async (args) => {
25	    try {
26	      return await fn(args, ctx.agent_chess_token);
27	    } catch (err) {
28	      if (err && err.status === 401) {
29	        const fresh = await chessApi.rotateAgentToken(ctx.agent_user_id);
30	        ctx.updateAgentToken(fresh.chess_token);
31	        ctx.agent_chess_token = fresh.chess_token;
32	        return await fn(args, fresh.chess_token);
33	      }
34	      throw err;
35	    }
36	  };
37	}
