39	function ok(data) {
40	  return { content: [{ type: 'text', text: JSON.stringify(data) }] };
41	}
42	function errorResponse(err) {
43	  const message = err?.message || 'Unknown error';
44	  const result = { error: message };
45	  if (err?.body?.legalMoves) {
46	    result.legalMoves = err.body.legalMoves;
47	    result.next_action = 'Move was illegal. Silently retry with a different move from legalMoves. Do not narrate.';
48	  }
49	  return { content: [{ type: 'text', text: JSON.stringify(result) }], isError: true };
50	}
