52	// Trim move/state responses to only what the agent needs to pick the next move.
53	// FEN encodes side-to-move + position, so board[] / currentTurn / moveHistory
54	// are dropped. Use get_board_state for the full payload.
55	function slim(state) {
56	  const out = {
57	    fen: state.fen,
58	    legalMoves: state.legalMoves,
59	    gameOver: state.gameOver === true || state.status === 'finished',
60	  };
61	  if (state.result) out.result = state.result;
62	  if (state.reason) out.reason = state.reason;
63	  return out;
64	}
